import { useState } from "react";

export function Hero({ title }) {
  const [count, setCount] = useState(0);
  return (
    <section data-testid="hero">
      <h1>{title}</h1>
      <p>Views: {count}</p>
      <button type="button" onClick={() => setCount((c) => c + 1)}>
        +1
      </button>
    </section>
  );
}

